def formula_map(ws):
    d={}
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value,str) and c.value.startswith('='):
                d[c.coordinate]=c.value
    return d
pairs = [('8. Income Statement','12. Income Statement (2)'),('8. Income Statement','15. Income Statement (3)'),('9. Cash Flow Statement','13. Cash Flow Statement (2)'),('9. Cash Flow Statement','16. Cash Flow Statement (3)'),('10. Balance Sheet','14. Balance Sheet (2)'),('10. Balance Sheet','17. Balance Sheet (3)'),('4. Projected Sales Forecast','5. Projected Sales Forecast (2)')]
for a,b in pairs:
    A=formula_map(wb[a]); B=formula_map(wb[b])
    onlyA=[c for c in A if c not in B]
    onlyB=[c for c in B if c not in A]
    diff=[c for c in A if c in B and A[c]!=B[c]][:100]
